import sys, threading, platform

rounds = int(input('How many times does each of two workers add 1 to the shared counter? (try 3): '))

def worker(name, store, locked):
    # one "add 1" is two steps: read the counter, then store the value plus one
    for _ in range(rounds):
        while locked and store['holder'] not in (None, name):
            yield (name, 'wait', None)
        if locked:
            store['holder'] = name
        seen = store['counter']
        yield (name, 'read', seen)
        store['counter'] = seen + 1
        yield (name, 'store', seen + 1)
        if locked:
            store['holder'] = None

def run(interleaved, locked):
    store = {'counter': 0, 'holder': None}
    workers = [worker('A', store, locked), worker('B', store, locked)]
    log = []
    if interleaved:                      # the scheduler gives each worker one step in turn
        while workers:
            for w in list(workers):
                try:
                    log.append(next(w))
                except StopIteration:
                    workers.remove(w)
    else:                                # one worker runs to the end, then the other
        for w in workers:
            log.extend(w)
    return store['counter'], log

expected = 2 * rounds
for title, interleaved, locked in [('one after the other', False, False),
                                   ('interleaved, no lock', True, False),
                                   ('interleaved, with a lock', True, True)]:
    counter, log = run(interleaved, locked)
    print('%-26s counter = %d of %d expected, %d updates lost' % (title + ':', counter, expected, expected - counter))
print('the first steps of the interleaved run without a lock:')
for step in run(True, False)[1][:8]:
    print('  ', step)

print()
